import { path } from '@servicenow/sdk-build-core'
import { createTestContext, loadTestFile } from '../test-utils'

/**
 * Bidirectionality Tests for SetFlowVariables and AssignSubflowOutputs
 *
 * Tests XML → Fluent transformation for FlowObject and FlowArray support
 * in setFlowVariables and assignSubflowOutputs operations.
 *
 * Validates:
 * 1. FlowArray with primitive types (string, integer, boolean, datetime)
 * 2. FlowArray with FlowObject elements
 * 3. FlowObject with nested FlowArrays (primitive types)
 * 4. Primitive array literals transformation
 * 5. Mixed datapills and static values
 */
describe('Flow Logic Variables - Bidirectionality (XML → Fluent)', () => {
    const ctx = createTestContext({ rootDir: path.resolve(__dirname, 'project') })
    beforeAll(() => ctx.initialize())
    afterEach(() => ctx.cleanup())
    describe('AssignSubflowOutputs - Primitive Arrays (XML → Fluent)', () => {
        test('AssignSubflowOutputs with primitive FlowArrays transforms correctly', async () => {
            const project = ctx.createProject()

            const xmlContent = loadTestFile('sys_hub_flow_aab7eed279314de5b3b3c41693b4e13b.xml', 'flow-logics/xmls')

            const { changedFiles } = await project.transform({
                path: 'sys_hub_flow_aab7eed279314de5b3b3c41693b4e13b.xml',
                content: xmlContent,
            })

            expect(changedFiles).toHaveLength(1)
            const content = changedFiles[0].getContent()

            // Verify Subflow structure
            expect(content).toContain('Subflow(')
            expect(content).toContain("name: 'Test Subflow - Primitive Arrays'")
            expect(content).toContain("description: 'Subflow with primitive type FlowArray outputs'")

            // Verify FlowArray outputs with primitive element types
            expect(content).toContain('stringList: FlowArray(')
            expect(content).toContain('elementType: StringColumn(')
            expect(content).toContain("childName: 'stringItem'")

            expect(content).toContain('numberList: FlowArray(')
            expect(content).toContain('elementType: IntegerColumn(')
            expect(content).toContain("childName: 'numberItem'")

            expect(content).toContain('booleanList: FlowArray(')
            expect(content).toContain('elementType: BooleanColumn(')
            expect(content).toContain("childName: 'booleanItem'")

            expect(content).toContain('dateList: FlowArray(')
            expect(content).toContain('elementType: StringColumn(') // DateTime stored as StringColumn
            expect(content).toContain("childName: 'dateItem'")

            // Verify assignSubflowOutputs with primitive array literals
            expect(content).toContain('wfa.flowLogic.assignSubflowOutputs(')

            // Test 1: String array literals
            expect(content).toContain("annotation: 'TEST 1: String Array'")
            expect(content).toContain("stringList: ['apple', 'banana', 'cherry']")

            // Test 2: Integer array literals
            expect(content).toContain("annotation: 'TEST 2: Integer Array'")
            expect(content).toContain('numberList: [10, 20, 30, 40]')

            // Test 3: Boolean array literals
            expect(content).toContain("annotation: 'TEST 3: Boolean Array'")
            expect(content).toContain('booleanList: [true, false, true]')

            // Test 4: DateTime array literals
            expect(content).toContain("annotation: 'TEST 4: DateTime Array'")
            expect(content).toContain("dateList: ['2024-01-01 10:00:00', '2024-02-15 14:30:00']")

            // Test 5: Empty array
            expect(content).toContain("annotation: 'TEST 5: Empty String Array'")
            expect(content).toContain('stringList: []')

            // Verify clean _params.outputs reference (not wrapped in dataPill)
            expect(content).toContain('_params.outputs,')
        })
    })

    describe('AssignSubflowOutputs - Complex Objects (XML → Fluent)', () => {
        test('AssignSubflowOutputs with FlowObjects and nested FlowArrays transforms correctly', async () => {
            const project = ctx.createProject()

            const xmlContent = loadTestFile('sys_hub_flow_b711dd5da8a141a48e3bd681354d42f9.xml', 'flow-logics/xmls')

            const { changedFiles } = await project.transform({
                path: 'sys_hub_flow_b711dd5da8a141a48e3bd681354d42f9.xml',
                content: xmlContent,
            })

            expect(changedFiles).toHaveLength(1)
            const content = changedFiles[0].getContent()

            // Verify Subflow structure
            expect(content).toContain('Subflow(')
            expect(content).toContain("name: 'Test Subflow - Complex Outputs'")

            // Verify FlowObject outputs
            expect(content).toContain('userInfo: FlowObject(')
            expect(content).toContain('fields: {')
            expect(content).toContain('name: StringColumn(')
            expect(content).toContain('email: StringColumn(')
            expect(content).toContain('age: IntegerColumn(')
            expect(content).toContain('isActive: BooleanColumn(')

            // Verify FlowArray with FlowObject elements
            expect(content).toContain('tags: FlowArray(')
            expect(content).toContain('elementType: FlowObject(')
            expect(content).toContain('value: StringColumn(')

            // Verify nested FlowObject structure
            expect(content).toContain('config: FlowObject(')
            expect(content).toContain('settings: FlowObject(')
            expect(content).toContain('timeout: IntegerColumn(')
            expect(content).toContain('retries: IntegerColumn(')
            expect(content).toContain('enabled: BooleanColumn(')

            // Verify FlowObject with nested FlowArray
            expect(content).toContain('project: FlowObject(')
            expect(content).toContain('tasks: FlowArray(')
            expect(content).toContain('taskName: StringColumn(')

            // Verify FlowObject with nested primitive FlowArrays
            expect(content).toContain('dataCollection: FlowObject(')
            expect(content).toContain('stringList: FlowArray(')
            expect(content).toContain('numberList: FlowArray(')
            expect(content).toContain('booleanList: FlowArray(')
            expect(content).toContain('dateList: FlowArray(')

            // Verify assignSubflowOutputs with object literals
            expect(content).toContain('wfa.flowLogic.assignSubflowOutputs(')

            // Verify object literal assignments exist
            expect(content).toMatch(/dataCollection:\s*{/)
            expect(content).toMatch(/stringList:\s*\[/)
            expect(content).toMatch(/numberList:\s*\[/)
            expect(content).toMatch(/booleanList:\s*\[/)
        })
    })

    describe('SetFlowVariables - Complex Flow (XML → Fluent)', () => {
        test('SetFlowVariables with FlowObjects and FlowArrays transforms correctly', async () => {
            const project = ctx.createProject()

            const xmlContent = loadTestFile('sys_hub_flow_eef5984c03d24cab9c699f6f7449bd13.xml', 'flow-logics/xmls')

            const { changedFiles } = await project.transform({
                path: 'sys_hub_flow_eef5984c03d24cab9c699f6f7449bd13.xml',
                content: xmlContent,
            })

            expect(changedFiles).toHaveLength(1)
            const content = changedFiles[0].getContent()

            // Verify Flow structure
            expect(content).toContain('Flow(')

            // Verify FlowArray flow variables
            expect(content).toContain('flowVariables:')
            expect(content).toContain('FlowArray(')

            // Verify FlowObject flow variables
            expect(content).toContain('FlowObject(')

            // Verify setFlowVariables operations
            expect(content).toContain('wfa.flowLogic.setFlowVariables(')

            // Verify array literals in assignments
            expect(content).toMatch(/:\s*\[/)

            // Verify object literals in assignments
            expect(content).toMatch(/:\s*{/)

            // Verify clean _params.flowVariables reference (not wrapped in dataPill)
            expect(content).toContain('_params.flowVariables,')
        })

        test('SetFlowVariables with mixed datapills and static values transforms correctly', async () => {
            const project = ctx.createProject()

            const xmlContent = loadTestFile('sys_hub_flow_eef5984c03d24cab9c699f6f7449bd13.xml', 'flow-logics/xmls')

            const { changedFiles } = await project.transform({
                path: 'sys_hub_flow_eef5984c03d24cab9c699f6f7449bd13.xml',
                content: xmlContent,
            })

            expect(changedFiles).toHaveLength(1)
            const content = changedFiles[0].getContent()

            // Verify datapills are preserved
            const dataPillPattern = /wfa\.dataPill\(_params\.trigger/
            expect(content).toMatch(dataPillPattern)

            // Verify template expressions with datapills
            const templatePattern = /`.*?\$\{wfa\.dataPill/
            expect(content).toMatch(templatePattern)
        })
    })

    describe('Edge Cases and Validation', () => {
        test('Empty arrays are preserved in transformation', async () => {
            const project = ctx.createProject()

            const xmlContent = loadTestFile('sys_hub_flow_aab7eed279314de5b3b3c41693b4e13b.xml', 'flow-logics/xmls')

            const { changedFiles } = await project.transform({
                path: 'sys_hub_flow_aab7eed279314de5b3b3c41693b4e13b.xml',
                content: xmlContent,
            })

            const content = changedFiles[0].getContent()

            // Verify empty arrays are correctly transformed
            expect(content).toContain('[]')
            expect(content).toMatch(/:\s*\[\s*\]/)
        })

        test('childName attribute is preserved in FlowArray transformation', async () => {
            const project = ctx.createProject()

            const xmlContent = loadTestFile('sys_hub_flow_aab7eed279314de5b3b3c41693b4e13b.xml', 'flow-logics/xmls')

            const { changedFiles } = await project.transform({
                path: 'sys_hub_flow_aab7eed279314de5b3b3c41693b4e13b.xml',
                content: xmlContent,
            })

            const content = changedFiles[0].getContent()

            // Verify childName is present for all FlowArrays
            const childNameMatches = content.match(/childName:\s*['"][\w]+['"]/g)
            expect(childNameMatches).toBeTruthy()
            expect(childNameMatches?.length).toBeGreaterThan(0)

            // Verify specific childName values
            expect(content).toContain("childName: 'stringItem'")
            expect(content).toContain("childName: 'numberItem'")
            expect(content).toContain("childName: 'booleanItem'")
            expect(content).toContain("childName: 'dateItem'")
        })

        test('Nested FlowObject structure is correctly reconstructed', async () => {
            const project = ctx.createProject()

            const xmlContent = loadTestFile('sys_hub_flow_b711dd5da8a141a48e3bd681354d42f9.xml', 'flow-logics/xmls')

            const { changedFiles } = await project.transform({
                path: 'sys_hub_flow_b711dd5da8a141a48e3bd681354d42f9.xml',
                content: xmlContent,
            })

            const content = changedFiles[0].getContent()

            // Verify nested FlowObject (config.settings)
            const nestedObjectPattern = /config:\s*FlowObject\(\s*{[\s\S]*?settings:\s*FlowObject\(/
            expect(content).toMatch(nestedObjectPattern)

            // Verify FlowObject with nested FlowArray (project.tasks)
            const objectWithArrayPattern = /project:\s*FlowObject\(\s*{[\s\S]*?tasks:\s*FlowArray\(/
            expect(content).toMatch(objectWithArrayPattern)
        })

        test('FlowArray and FlowObject are correctly used in flow variables', async () => {
            const project = ctx.createProject()

            const xmlContent = loadTestFile('sys_hub_flow_eef5984c03d24cab9c699f6f7449bd13.xml', 'flow-logics/xmls')

            const { changedFiles } = await project.transform({
                path: 'sys_hub_flow_eef5984c03d24cab9c699f6f7449bd13.xml',
                content: xmlContent,
            })

            const content = changedFiles[0].getContent()

            // Verify FlowArray is used in flow variables
            expect(content).toContain('FlowArray(')

            // Verify FlowObject is used in flow variables
            expect(content).toContain('FlowObject(')

            // Verify setFlowVariables assignments exist
            expect(content).toContain('wfa.flowLogic.setFlowVariables(')
        })
    })
})
